```import { assertEquals } from "<https://deno.land/std@0.100.0/testing/asserts.ts>";
import { test } from "<https://deno.land/x/denops_std@v1.3.0/test/mod.ts>";
import * as autocmd from "<https://deno.land/x/denops_std@v1.3.0/autocmd/mod.ts>";

test({
  mode: "vim",
  name: "input() returns user input text",
  fn: async (denops) =&gt; {
    await autocmd.group(denops, "denops_std_function_input", (helper) =&gt; {
      helper.remove("*");
      helper.define(
        "CmdlineEnter",
        "*",
        `call feedkeys("Hello world!\n", "n")`,
        {
          once: true,
        },
      );
    });
    const result = await denops.call("input", "Test: ") as string;
    assertEquals(result, "Hello world!");
  },
});```

