Gin で使うためにアクションの実装を始めた

```export async function init(denops: Denops) {
  const [choiceId, repeatId, helpId] = anonymous.add(
    denops,
    () =&gt; {
      // choice
    },
    () =&gt; {
      // repeat
    },
    () =&gt; {
      // help
    },
  );
  const [hasChoice, hasRepeat, hasHelp] = await batch.gather(denops, async (denops) =&gt; {
    await fn.hasmapto(denops, `&lt;Plug&gt;(gin-action-choice)`, "n");
    await fn.hasmapto(denops, `&lt;Plug&gt;(gin-action-repeat)`, "n");
    await fn.hasmapto(denops, `&lt;Plug&gt;(gin-action-help)`, "n");
  });
  await batch.batch(denops, async (denops) =&gt; {
    await mapping.map(
      denops,
      "&lt;Plug&gt;(gin-action-choice)",
      `:&lt;C-u&gt;call denops#request('${denops.name}', '${choiceId}', [])&lt;CR&gt;`,
      { mode: "n", noremap: true, buffer: true, silent: true },
    );
    await mapping.map(
      denops,
      "&lt;Plug&gt;(gin-action-repeat)",
      `:&lt;C-u&gt;call denops#request('${denops.name}', '${repeatId}', [])&lt;CR&gt;`,
      { mode: "n", noremap: true, buffer: true, silent: true },
    );
    await mapping.map(
      denops,
      "&lt;Plug&gt;(gin-action-help)",
      `:&lt;C-u&gt;call denops#request('${denops.name}', '${helpId}', [])&lt;CR&gt;`,
      { mode: "n", noremap: true, buffer: true, silent: true },
    );
    await mapping.map(
      denops,
      "&lt;Plug&gt;(gin-action-help:all)",
      `:&lt;C-u&gt;call denops#request('${denops.name}', '${helpId}', [v:true])&lt;CR&gt;`,
      { mode: "n", noremap: true, buffer: true, silent: true },
    );
    if (!hasChoice) {
      await mapping.map(denops, "a", "&lt;Plug&gt;(gin-action-choice)", { mode: "n", buffer: true });
    }
    if (!hasRepeat) {
      await mapping.map(denops, ".", "&lt;Plug&gt;(gin-action-repeat)", { mode: "n", buffer: true });
    }
    if (!hasHelp) {
      await mapping.map(denops, "?", "&lt;Plug&gt;(gin-action-help)", { mode: "n", buffer: true });
    }
  });
}```
